"use client"

import { useEffect, useState } from "react"
import { PortalShell, StateMessage } from "../../components/PortalShell"
import { api } from "../../lib/api"

type Order = { id: string; orderNumber: string; status: string; totalAmount: string | number; items: { productNameSnapshot: string | null; orderedQuantity: string | number }[]; payments: { status: string }[]; deliveries: { assignments: { user?: { name: string } }[] }[] }
type Partner = { userId: string; user: { name: string } }
type Identity = { vendor: { id: string } | null }

export default function VendorOrders() {
  const [vendorId, setVendorId] = useState(""); const [orders, setOrders] = useState<Order[]>([]); const [partners, setPartners] = useState<Partner[]>([]); const [selected, setSelected] = useState<Record<string, string>>({}); const [message, setMessage] = useState(""); const [error, setError] = useState("")
  async function load() { try { const identity = await api<Identity>("/api/v1/marketplace/me"); if (!identity.vendor) throw new Error("Vendor access is not configured"); setVendorId(identity.vendor.id); const [nextOrders, nextPartners] = await Promise.all([api<Order[]>(`/api/v1/marketplace/vendors/${identity.vendor.id}/orders`), api<Partner[]>(`/api/v1/marketplace/vendors/${identity.vendor.id}/delivery-partners`)]); setOrders(nextOrders); setPartners(nextPartners) } catch (e) { setError(e instanceof Error ? e.message : "Unable to load orders") } }
  useEffect(() => { load() }, [])
  async function updateStatus(id: string, status: string) { try { await api(`/api/v1/marketplace/orders/${id}/status`, { method: "POST", body: JSON.stringify({ status }) }); setMessage(`Order moved to ${status}`); await load() } catch (e) { setError(e instanceof Error ? e.message : "Unable to update order") } }
  async function assign(id: string) { try { await api(`/api/v1/marketplace/orders/${id}/assignment`, { method: "POST", body: JSON.stringify({ userId: selected[id] }) }); setMessage("Delivery partner assigned"); await load() } catch (e) { setError(e instanceof Error ? e.message : "Unable to assign delivery") } }
  return <PortalShell title="Vendor orders" subtitle="Process only orders belonging to your vendor." links={[{ label: "Dashboard", href: "/vendor/dashboard" }, { label: "Products", href: "/vendor/products" }, { label: "Orders", href: "/vendor/orders" }, { label: "Delivery partners", href: "/vendor/delivery-partners" }, { label: "Payments", href: "/vendor/payments" }]}>{message && <StateMessage>{message}</StateMessage>}{error && <StateMessage error>{error}</StateMessage>}<section className="portal-panel">{orders.length === 0 ? <div className="portal-empty">No orders found.</div> : <table className="portal-table"><thead><tr><th>Order</th><th>Items</th><th>Amount</th><th>Status</th><th>Payment</th><th>Delivery partner</th><th>Actions</th></tr></thead><tbody>{orders.map((order) => <tr key={order.id}><td><strong>{order.orderNumber}</strong></td><td>{order.items.map((item) => `${item.productNameSnapshot || "Product"} × ${item.orderedQuantity}`).join(", ")}</td><td>₹{Number(order.totalAmount).toLocaleString("en-IN")}</td><td><span className="status-badge">{order.status.replaceAll("_", " ")}</span></td><td>{order.payments.some((payment) => payment.status === "COMPLETED") ? "Collected" : "Pending"}</td><td>{order.deliveries[0]?.assignments[0]?.user?.name || "Unassigned"}</td><td><div className="portal-actions">{order.status === "PLACED" && <button onClick={() => updateStatus(order.id, "CONFIRMED")}>Confirm</button>}{order.status === "CONFIRMED" && <button onClick={() => updateStatus(order.id, "PICKING")}>Start packing</button>}{order.status === "PICKING" && <button onClick={() => updateStatus(order.id, "PACKED")}>Mark packed</button>}{order.status === "PACKED" && <><select value={selected[order.id] || ""} onChange={(event) => setSelected({ ...selected, [order.id]: event.target.value })}><option value="">Partner</option>{partners.map((partner) => <option key={partner.userId} value={partner.userId}>{partner.user.name}</option>)}</select><button className="primary" disabled={!selected[order.id]} onClick={() => assign(order.id)}>Assign</button></>}</div></td></tr>)}</tbody></table>}</section></PortalShell>
}
